        ChatRoom contohChatRoom = new ChatRoom("Contoh Chat Room");

        User naomi = new User("Naomi");
        User dodo = new User("Dodo");
        User andi =  new User("Andi");
        User fiona =  new User("Fiona");

        contohChatRoom.registerUser(naomi);
